import { useEffect, useMemo, useState } from "react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { Activity, AlertTriangle, CheckCircle2, Copy, GitBranch, PlugZap, RefreshCw, RotateCcw, ShieldAlert, Webhook } from "lucide-react";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { useToast } from "@/hooks/use-toast";
import { apiRequest } from "@/lib/queryClient";

type Row = Record<string, any>;
type Props = { root: string; canExecute: boolean; canDecide: boolean; canApprove: boolean };
const field = "h-10 rounded-md border border-input bg-background px-3 text-sm";
function scopedUrl(url: string) { if (typeof window === "undefined") return url; const seat = new URLSearchParams(window.location.search).get("seat"); if (!seat) return url; const scoped = new URL(url, window.location.origin); scoped.searchParams.set("seatId", seat); return `${scoped.pathname}${scoped.search}`; }
async function json<T>(method: "GET" | "POST", url: string, body?: unknown): Promise<T> { const response = await apiRequest(method, scopedUrl(url), body) as Response; return response.json() as Promise<T>; }
const csv = (value: string) => value.split(",").map((item) => item.trim()).filter(Boolean);
function badge(value: string) { const good = ["succeeded", "passing", "native", "resolved", "active", "observed"].includes(value); const bad = ["failed", "uncertain", "dead_letter", "critical", "failing", "expired", "revoked"].includes(value); return <Badge variant={(good ? "default" : bad ? "destructive" : "secondary") as any}>{value.replaceAll("_", " ")}</Badge>; }

export function IntegrationOperationsControlCenter({ root, canExecute, canDecide, canApprove }: Props) {
  const endpoint = `${root}/integration-operations`; const queryClient = useQueryClient(); const { toast } = useToast();
  const state = useQuery<Row>({ queryKey: [endpoint], queryFn: () => json("GET", endpoint) });
  const providerIngressEndpoint = `${root}/provider-ingress`;
  const providerIngress = useQuery<Row>({ queryKey: [providerIngressEndpoint], queryFn: () => json("GET", providerIngressEndpoint) });
  const refresh = async () => { await Promise.all([queryClient.invalidateQueries({ queryKey: [endpoint] }), queryClient.invalidateQueries({ queryKey: [providerIngressEndpoint] })]); };
  const action = useMutation({ mutationFn: (input: { url: string; body: unknown; success: string }) => json("POST", input.url, input.body), onSuccess: async (_value, input) => { await refresh(); toast({ title: input.success, description: "Operational projection, policy decision, and immutable receipt history were updated together." }); }, onError: (error) => toast({ title: "Integration operation failed", description: error instanceof Error ? error.message : String(error), variant: "destructive" }) });
  const webhookAction = useMutation({ mutationFn: (input: { url: string; body: unknown; success: string }) => json<Row>("POST", input.url, input.body), onSuccess: async (value, input) => { if (value.secret) setRevealedWebhookSecret(value.secret); await refresh(); toast({ title: input.success, description: value.secret ? "Save the new signing secret now. EOS will not display it again." : "The endpoint projection and immutable history were updated together." }); }, onError: (error) => toast({ title: "Signed endpoint operation failed", description: error instanceof Error ? error.message : String(error), variant: "destructive" }) });
  const runAction = (url: string, body: unknown, success: string) => action.mutate({ url, body, success });
  const [bindingId, setBindingId] = useState(""); const [runId, setRunId] = useState("");
  const [manifest, setManifest] = useState({ contractVersion: "1.0.0", evidenceId: "" });
  const [run, setRun] = useState({ operation: "", idempotencyKey: "", requestReference: "", requestShape: "{}", maxAttempts: 3, ownerSeatId: "", classification: "restricted" });
  const [receipt, setReceipt] = useState({ outcome: "succeeded", authority: "provider_receipt", externalReference: "", summary: "", responseShape: "{}", latencyMs: "", evidenceId: "" });
  const [execution, setExecution] = useState({ evidenceId: "", confirmed: false });
  const [retry, setRetry] = useState({ rationale: "", evidenceId: "" });
  const [fallback, setFallback] = useState({ trafficMode: "manual_fallback", rationale: "", evidenceId: "" });
  const [qualification, setQualification] = useState({ qualificationKey: "", environment: "sandbox", outcome: "passing", testedOperations: "", missingCapabilities: "", testSummary: "", rollbackValidated: false, evidenceId: "" });
  const [cutover, setCutover] = useState({ decision: "approve_native", rationale: "", evidenceId: "" });
  const [incidentNotes, setIncidentNotes] = useState<Record<string, { rationale: string; evidenceId: string }>>({});
  const [webhookForm, setWebhookForm] = useState({ acceptedEventTypes: "", evidenceId: "", gracePeriodMinutes: 15 });
  const [revealedWebhookSecret, setRevealedWebhookSecret] = useState("");
  const [providerIngressForm, setProviderIngressForm] = useState({ providerAccountReference: "", providerSubscriptionReference: "", resourceCollectionReference: "", topicName: "", audience: "", serviceAccountEmail: "", evidenceId: "", confirmed: false });
  const [providerRotation, setProviderRotation] = useState({ providerSubscriptionReference: "", resourceCollectionReference: "", topicName: "", audience: "", serviceAccountEmail: "", rationale: "", evidenceId: "", confirmed: false });
  const [nativeProviderChoice, setNativeProviderChoice] = useState<"gmail" | "google_drive" | "google_calendar">("gmail");
  const [providerReplay, setProviderReplay] = useState({ rationale: "", evidenceId: "" });
  const [providerPolicyForm, setProviderPolicyForm] = useState({ watchRenewBeforeMinutes: 1440, reconciliationOverdueMinutes: 15, pendingVerificationMinutes: 60, externalEscalationEnabled: false, minimumEscalationSeverity: "material", maxDeliveryAttempts: 5, rationale: "", evidenceId: "" });
  const [providerAlertReplay, setProviderAlertReplay] = useState({ rationale: "", evidenceId: "" });
  const [providerAlertAcknowledgementNotes, setProviderAlertAcknowledgementNotes] = useState<Record<string, string>>({});
  const [revealedNotionToken, setRevealedNotionToken] = useState("");

  const bindings = state.data?.bindings || []; const selectedBinding = bindings.find((item: Row) => item.id === bindingId);
  const manifests = useMemo(() => (state.data?.manifests || []).filter((item: Row) => item.integrationBindingId === bindingId), [state.data?.manifests, bindingId]);
  const currentManifest = manifests.find((item: Row) => item.bindingConfigurationVersion === selectedBinding?.configurationVersion);
  const operational = (state.data?.operationalStates || []).find((item: Row) => item.integrationBindingId === bindingId);
  const runs = useMemo(() => (state.data?.runs || []).filter((item: Row) => item.integrationBindingId === bindingId), [state.data?.runs, bindingId]);
  const selectedRun = runs.find((item: Row) => item.id === runId);
  const receipts = (state.data?.receipts || []).filter((item: Row) => item.runId === runId);
  const providerExecutions = (state.data?.providerExecutions || []).filter((item: Row) => item.request?.integrationRunId === runId);
  const incidents = (state.data?.incidents || []).filter((item: Row) => item.integrationBindingId === bindingId);
  const qualifications = (state.data?.qualifications || []).filter((item: Row) => item.integrationBindingId === bindingId);
  const currentQualification = qualifications.find((item: Row) => item.id === operational?.currentQualificationId);
  const events = (state.data?.events || []).filter((item: Row) => item.integrationBindingId === bindingId);
  const webhookEndpoint = (state.data?.webhookEndpoints || []).find((item: Row) => item.integrationBindingId === bindingId);
  const webhookEvents = (state.data?.webhookEvents || []).filter((item: Row) => item.integrationBindingId === bindingId);
  const bindingProviderKey = selectedBinding?.providerKey?.toLowerCase().replaceAll("-", "_") || "";
  const isGoogleWorkspaceBinding = bindingProviderKey.includes("google_workspace") || bindingProviderKey === "google";
  const nativeProvider = bindingProviderKey.includes("notion") ? "notion" : bindingProviderKey.includes("gmail") ? "gmail" : isGoogleWorkspaceBinding ? nativeProviderChoice : bindingProviderKey.includes("google_drive") ? "google_drive" : "";
  const nativeIngress = (providerIngress.data?.registrations || []).find((item: Row) => item.integrationBindingId === bindingId && item.provider === nativeProvider);
  const nativeIngressEvents = (providerIngress.data?.events || []).filter((item: Row) => item.integrationBindingId === bindingId);
  const nativeReconciliationAttempts = (providerIngress.data?.reconciliationAttempts || []).filter((item: Row) => item.registrationId === nativeIngress?.id);
  const nativeWatchAttempts = (providerIngress.data?.watchAttempts || []).filter((item: Row) => item.registrationId === nativeIngress?.id);
  const nativeOperationalAlerts = (providerIngress.data?.health?.alerts || []).filter((item: Row) => item.integrationBindingId === bindingId);
  const nativePolicy = (providerIngress.data?.policies || []).find((item: Row) => item.registrationId === nativeIngress?.id);
  const nativeAlertDeliveryAttempts = (providerIngress.data?.alertDeliveryAttempts || []).filter((item: Row) => item.registrationId === nativeIngress?.id);
  const nativeAlertAcknowledgements = (providerIngress.data?.alertAcknowledgements || []).filter((item: Row) => item.registrationId === nativeIngress?.id);
  const nativeResourceSnapshots = (providerIngress.data?.resourceSnapshots || []).filter((item: Row) => item.registrationId === nativeIngress?.id);
  const evidence = state.data?.evidence || [];
  const evidenceSelect = (label: string, value: string, onChange: (value: string) => void) => <select aria-label={label} className={field} value={value} onChange={(event) => onChange(event.target.value)}><option value="">Choose verified Evidence</option>{evidence.map((item: Row) => <option key={item.id} value={item.id}>{item.title} · {item.evidenceType}</option>)}</select>;
  const parseShape = (value: string) => { try { return JSON.parse(value); } catch { toast({ title: "Invalid JSON", description: "Request and response shapes must be valid JSON objects.", variant: "destructive" }); return null; } };

  useEffect(() => {
    if (!nativePolicy) return;
    setProviderPolicyForm((value) => ({ ...value, watchRenewBeforeMinutes: nativePolicy.watchRenewBeforeMinutes, reconciliationOverdueMinutes: nativePolicy.reconciliationOverdueMinutes, pendingVerificationMinutes: nativePolicy.pendingVerificationMinutes, externalEscalationEnabled: nativePolicy.externalEscalationEnabled, minimumEscalationSeverity: nativePolicy.minimumEscalationSeverity, maxDeliveryAttempts: nativePolicy.maxDeliveryAttempts }));
  }, [nativePolicy?.registrationId, nativePolicy?.version]);

  if (state.isLoading) return <Card><CardContent className="py-10 text-center text-sm text-muted-foreground">Loading adapter operations…</CardContent></Card>;
  if (state.isError) return <Alert variant="destructive"><ShieldAlert className="h-4 w-4"/><AlertTitle>Adapter operations unavailable</AlertTitle><AlertDescription>EOS will not infer provider execution, recovery, or cutover state while the governed ledger is unavailable.</AlertDescription></Alert>;

  return <div className="space-y-6" id="integration-operations-control-center">
    <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{[["Bindings", state.data?.counts?.bindings], ["Frozen contracts", state.data?.counts?.frozenContracts], ["Open runs", state.data?.counts?.openRuns], ["Failed runs", state.data?.counts?.failedRuns], ["Open incidents", state.data?.counts?.openIncidents], ["Signed endpoints", state.data?.counts?.activeWebhookEndpoints], ["Unmatched events", state.data?.counts?.unmatchedWebhookEvents], ["Native cutovers", state.data?.counts?.nativeCutovers]].map(([label, value]) => <Card key={String(label)}><CardContent className="pt-5"><p className="text-xs uppercase tracking-wide text-muted-foreground">{label}</p><p className="mt-2 text-2xl font-semibold">{value || 0}</p></CardContent></Card>)}</div>
    <Alert><ShieldAlert className="h-4 w-4"/><AlertTitle>Provider execution boundary</AlertTitle><AlertDescription>{state.data?.boundary} Native dispatch is {state.data?.executionCapability?.enabled ? "enabled" : "disabled"} in this deployment. Audited operations: {(state.data?.executionCapability?.operations || []).join(" · ") || "none"}.</AlertDescription></Alert>

    <Card><CardHeader><CardTitle className="flex items-center gap-2"><PlugZap className="h-5 w-5"/>Adapter contract and live mode</CardTitle><CardDescription>Freeze the exact capability contract before a run. Configuration changes invalidate the prior manifest and qualification.</CardDescription></CardHeader><CardContent className="space-y-4">
      <div className="flex flex-col gap-2 md:flex-row"><select aria-label="Integration binding" className={`${field} flex-1`} value={bindingId} onChange={(event) => { setBindingId(event.target.value); setRunId(""); setRevealedWebhookSecret(""); setWebhookForm((value) => ({ ...value, acceptedEventTypes: "" })); }}><option value="">Choose integration binding</option>{bindings.map((item: Row) => <option key={item.id} value={item.id}>{item.name} · {item.providerKey} · config v{item.configurationVersion}</option>)}</select><Button variant="outline" onClick={() => refresh()} disabled={state.isFetching}><RefreshCw className={`mr-2 h-4 w-4 ${state.isFetching ? "animate-spin" : ""}`}/>Refresh</Button></div>
      {selectedBinding && <div className="rounded-xl border p-4"><div className="flex flex-wrap gap-2">{badge(selectedBinding.lifecycleState)}{badge(selectedBinding.connectionState)}{badge(selectedBinding.healthState)}{badge(operational?.trafficMode || "provider")}<Badge variant="outline">config v{selectedBinding.configurationVersion}</Badge></div><p className="mt-3 font-semibold">{selectedBinding.name}</p><p className="mt-1 text-sm text-muted-foreground">{(selectedBinding.operations || []).join(" · ") || "No operations declared"}</p><p className="mt-2 text-xs">Fallback: {selectedBinding.manualFallback}</p></div>}
      {selectedBinding && !currentManifest && canDecide && <div className="grid gap-2 rounded-xl border p-4 md:grid-cols-3"><Input placeholder="Contract version" value={manifest.contractVersion} onChange={(e) => setManifest((v) => ({ ...v, contractVersion: e.target.value }))}/>{evidenceSelect("Manifest Evidence", manifest.evidenceId, (evidenceId) => setManifest((v) => ({ ...v, evidenceId })))}<Button disabled={!manifest.evidenceId || !manifest.contractVersion} onClick={() => runAction(`${endpoint}/manifests`, { integrationBindingId: bindingId, contractVersion: manifest.contractVersion, evidenceIds: [manifest.evidenceId] }, "Adapter capability contract frozen")}>Freeze current contract</Button></div>}
      {currentManifest && <div className="rounded-lg bg-muted p-3 text-xs"><p className="font-medium">Current manifest {currentManifest.contractVersion}</p><code className="mt-1 block break-all">{currentManifest.manifestSha256}</code></div>}
      {selectedBinding && operational && canDecide && <details><summary className="cursor-pointer text-sm font-medium">Change fallback or provider traffic mode</summary><div className="mt-3 grid gap-2 md:grid-cols-2"><select aria-label="Traffic mode" className={field} value={fallback.trafficMode} onChange={(e) => setFallback((v) => ({ ...v, trafficMode: e.target.value }))}>{["manual_fallback", "paused", "provider"].map((value) => <option key={value}>{value.replaceAll("_", " ")}</option>)}</select>{evidenceSelect("Fallback Evidence", fallback.evidenceId, (evidenceId) => setFallback((v) => ({ ...v, evidenceId })))}<Textarea className="md:col-span-2" placeholder="Trigger, scope, operator handoff, and restoration rationale" value={fallback.rationale} onChange={(e) => setFallback((v) => ({ ...v, rationale: e.target.value }))}/><Button className="w-fit" disabled={!fallback.evidenceId || fallback.rationale.trim().length < 20 || fallback.trafficMode === operational.trafficMode} onClick={() => runAction(`${endpoint}/bindings/${bindingId}/fallback`, { expectedVersion: operational.version, trafficMode: fallback.trafficMode, rationale: fallback.rationale, evidenceIds: [fallback.evidenceId] }, `Traffic mode changed to ${fallback.trafficMode.replaceAll("_", " ")}`)}><RotateCcw className="mr-2 h-4 w-4"/>Record mode change</Button></div></details>}
    </CardContent></Card>

    <Card id="signed-adapter-webhook-ingress"><CardHeader><CardTitle className="flex items-center gap-2"><Webhook className="h-5 w-5"/>Signed adapter event ingress</CardTitle><CardDescription>Provision an EOS-owned callback contract for an adapter gateway. This does not claim Gmail, Notion, or another provider emits this envelope directly.</CardDescription></CardHeader><CardContent className="space-y-4">
      {!selectedBinding ? <p className="text-sm text-muted-foreground">Choose an integration binding to inspect or provision its signed endpoint.</p> : webhookEndpoint ? <div className="space-y-3 rounded-xl border p-4"><div className="flex flex-wrap items-center justify-between gap-2"><div className="flex flex-wrap gap-2">{badge(webhookEndpoint.state)}<Badge variant="outline">v{webhookEndpoint.version}</Badge><Badge variant="outline">HMAC SHA-256</Badge></div><span className="text-xs text-muted-foreground">{webhookEndpoint.lastInboundEventAt ? `Last event ${new Date(webhookEndpoint.lastInboundEventAt).toLocaleString()}` : "No events received"}</span></div><div><p className="text-xs font-medium uppercase tracking-wide text-muted-foreground">Callback URL</p><code className="mt-1 block break-all rounded bg-muted p-2 text-xs">{webhookEndpoint.endpointUrl || webhookEndpoint.endpointPath}</code></div><div><p className="text-xs font-medium uppercase tracking-wide text-muted-foreground">Accepted events</p><p className="mt-1 text-sm">{(webhookEndpoint.acceptedEventTypes || []).join(" · ")}</p></div><p className="break-all text-xs text-muted-foreground">Secret fingerprint {webhookEndpoint.secretFingerprint}</p>{canDecide && <div className="grid gap-2 border-t pt-3 md:grid-cols-3">{evidenceSelect("Webhook endpoint Evidence", webhookForm.evidenceId, (evidenceId) => setWebhookForm((value) => ({ ...value, evidenceId })))}<Input type="number" min={0} max={1440} aria-label="Previous-secret grace period in minutes" value={webhookForm.gracePeriodMinutes} onChange={(event) => setWebhookForm((value) => ({ ...value, gracePeriodMinutes: Number(event.target.value) }))}/><div className="flex flex-wrap gap-2"><Button variant="outline" disabled={!webhookForm.evidenceId || webhookAction.isPending} onClick={() => { setRevealedWebhookSecret(""); webhookAction.mutate({ url: `${endpoint}/webhook-endpoints/${webhookEndpoint.id}/rotate-secret`, body: { expectedVersion: webhookEndpoint.version, gracePeriodMinutes: webhookForm.gracePeriodMinutes, evidenceIds: [webhookForm.evidenceId] }, success: "Signing secret rotated" }); }}><RotateCcw className="mr-2 h-4 w-4"/>Rotate secret</Button><Button variant={webhookEndpoint.state === "active" ? "destructive" : "default"} disabled={!webhookForm.evidenceId || webhookAction.isPending} onClick={() => webhookAction.mutate({ url: `${endpoint}/webhook-endpoints/${webhookEndpoint.id}/state`, body: { expectedVersion: webhookEndpoint.version, state: webhookEndpoint.state === "active" ? "revoked" : "active", evidenceIds: [webhookForm.evidenceId] }, success: webhookEndpoint.state === "active" ? "Signed endpoint revoked" : "Signed endpoint activated" })}>{webhookEndpoint.state === "active" ? "Revoke" : "Activate"}</Button></div></div>}</div> : canDecide ? <div className="grid gap-2 rounded-xl border p-4 md:grid-cols-3"><Input className="md:col-span-2" placeholder={(selectedBinding.expectedEvents || []).join(", ") || "Declared event types, comma separated"} aria-label="Accepted adapter event types" value={webhookForm.acceptedEventTypes} onChange={(event) => setWebhookForm((value) => ({ ...value, acceptedEventTypes: event.target.value }))}/>{evidenceSelect("Webhook provisioning Evidence", webhookForm.evidenceId, (evidenceId) => setWebhookForm((value) => ({ ...value, evidenceId })))}<p className="text-xs text-muted-foreground md:col-span-2">Only event types already declared by the current binding are accepted: {(selectedBinding.expectedEvents || []).join(" · ") || "none declared"}.</p><Button disabled={!webhookForm.evidenceId || !csv(webhookForm.acceptedEventTypes).length || webhookAction.isPending} onClick={() => { setRevealedWebhookSecret(""); webhookAction.mutate({ url: `${endpoint}/bindings/${bindingId}/webhook-endpoints`, body: { acceptedEventTypes: csv(webhookForm.acceptedEventTypes), evidenceIds: [webhookForm.evidenceId] }, success: "Signed adapter endpoint provisioned" }); }}>Provision endpoint</Button></div> : <p className="text-sm text-muted-foreground">No managed signed endpoint is configured for this binding.</p>}
      {revealedWebhookSecret && <Alert><ShieldAlert className="h-4 w-4"/><AlertTitle>One-time signing secret</AlertTitle><AlertDescription><p>Copy this secret into the adapter gateway now. Refreshing or leaving this view permanently hides it.</p><div className="mt-3 flex gap-2"><Input readOnly aria-label="One-time adapter signing secret" value={revealedWebhookSecret}/><Button variant="outline" aria-label="Copy adapter signing secret" onClick={async () => { await navigator.clipboard.writeText(revealedWebhookSecret); toast({ title: "Signing secret copied", description: "Store it only in the adapter's secret manager." }); }}><Copy className="h-4 w-4"/></Button></div></AlertDescription></Alert>}
      <div className="space-y-2"><div className="flex items-center justify-between"><p className="text-sm font-medium">Verified event inbox</p><Badge variant="secondary">{webhookEvents.length}</Badge></div>{webhookEvents.length ? webhookEvents.slice(0, 25).map((item: Row) => <div key={item.id} className="rounded-lg border p-3 text-xs"><div className="flex flex-wrap justify-between gap-2"><span className="font-medium">{item.eventType}</span><div className="flex gap-2">{badge(item.outcome)}{badge(item.processingState)}</div></div><p className="mt-1 text-muted-foreground">{item.summary}</p><p className="mt-1 break-all">{item.externalReference}</p>{item.matchedRunId && <p className="mt-1 text-muted-foreground">Matched run {item.matchedRunId}</p>}</div>) : <p className="text-sm text-muted-foreground">No verified adapter events have arrived for this binding.</p>}</div>
    </CardContent></Card>

    <Card id="provider-native-ingress"><CardHeader><CardTitle className="flex items-center gap-2"><Webhook className="h-5 w-5"/>Provider-native ingress</CardTitle><CardDescription>Receive signed Notion events, authenticated Gmail signals, and token-authenticated Google Drive or Calendar resource notifications. Every signal is reconciled before EOS records provider state.</CardDescription></CardHeader><CardContent className="space-y-4">
      {nativeOperationalAlerts.length > 0 && <div className="space-y-2" aria-label="Provider ingress actions required">{nativeOperationalAlerts.map((item: Row) => { const delivery = nativeAlertDeliveryAttempts.find((attempt: Row) => attempt.alertKey === item.alertKey); const acknowledgement = nativeAlertAcknowledgements.find((receipt: Row) => receipt.alertKey === item.alertKey); const acknowledgementNote = providerAlertAcknowledgementNotes[item.alertKey] || ""; return <Alert key={item.id} variant={item.severity === "critical" ? "destructive" : "default"}><AlertTriangle className="h-4 w-4"/><AlertTitle>{item.summary}</AlertTitle><AlertDescription>{item.detail}<span className="mt-1 block text-xs font-medium">Required action: {item.action.replaceAll("_", " ")}</span>{delivery && <span className="mt-1 block text-xs">Escalation: {delivery.outcome.replaceAll("_", " ")} · attempt {delivery.attemptNumber}</span>}{acknowledgement ? <div className="mt-3 rounded-lg border bg-background/70 p-3 text-xs"><div className="flex flex-wrap items-center justify-between gap-2"><span className="font-medium">Human responsibility acknowledged</span><Badge variant="outline">{new Date(acknowledgement.acknowledgedAt).toLocaleString()}</Badge></div><p className="mt-1">{acknowledgement.acknowledgementNote}</p><code className="mt-1 block break-all text-[10px] text-muted-foreground">{acknowledgement.receiptSha256}</code><p className="mt-1 text-muted-foreground">Acknowledgement does not resolve or suppress this alert.</p></div> : canDecide && <div className="mt-3 grid gap-2 border-t pt-3"><Textarea aria-label={`Acknowledgement note for ${item.kind}`} placeholder="Who is taking responsibility, the immediate containment step, and the next check" value={acknowledgementNote} onChange={(event) => setProviderAlertAcknowledgementNotes((value) => ({ ...value, [item.alertKey]: event.target.value }))}/><Button variant="outline" className="w-fit" disabled={acknowledgementNote.trim().length < 10 || action.isPending} onClick={() => runAction(`${providerIngressEndpoint}/${item.registrationId}/alerts/${item.alertKey}/acknowledge`, { acknowledgementNote, evidenceIds: [] }, "Provider alert acknowledged")}><CheckCircle2 className="mr-2 h-4 w-4"/>Acknowledge responsibility</Button></div>}{delivery?.outcome === "dead_letter" && canDecide && <div className="mt-3 grid gap-2 border-t pt-3"><Textarea aria-label={`Alert replay rationale for ${item.kind}`} placeholder="Why the receiver is ready and replaying this current escalation is safe" value={providerAlertReplay.rationale} onChange={(event) => setProviderAlertReplay((value) => ({ ...value, rationale: event.target.value }))}/>{evidenceSelect(`Alert replay Evidence for ${item.kind}`, providerAlertReplay.evidenceId, (evidenceId) => setProviderAlertReplay((value) => ({ ...value, evidenceId })))}<Button variant="outline" disabled={!providerAlertReplay.evidenceId || providerAlertReplay.rationale.trim().length < 20 || action.isPending} onClick={() => runAction(`${providerIngressEndpoint}/${item.registrationId}/alerts/${item.alertKey}/replay`, { rationale: providerAlertReplay.rationale, evidenceIds: [providerAlertReplay.evidenceId] }, "Provider escalation replayed")}><RotateCcw className="mr-2 h-4 w-4"/>Replay escalation</Button></div>}</AlertDescription></Alert>; })}</div>}
      {selectedBinding && isGoogleWorkspaceBinding && <label className="grid gap-1 text-xs font-medium"><span>Google Workspace signal surface</span><select aria-label="Google Workspace signal surface" className={field} value={nativeProviderChoice} onChange={(event) => { setNativeProviderChoice(event.target.value as typeof nativeProviderChoice); setRevealedNotionToken(""); setProviderIngressForm((value) => ({ ...value, confirmed: false })); }}><option value="gmail">Gmail mailbox history</option><option value="google_drive">Google Drive changes</option><option value="google_calendar">Google Calendar events</option></select></label>}
      {!selectedBinding ? <p className="text-sm text-muted-foreground">Choose an integration binding to configure its provider-native callback.</p> : !nativeProvider ? <p className="text-sm text-muted-foreground">This binding does not expose a supported provider-native signal surface.</p> : nativeIngress ? <div className="space-y-3 rounded-xl border p-4">
        <div className="flex flex-wrap items-center justify-between gap-2"><div className="flex flex-wrap gap-2">{badge(nativeIngress.state)}<Badge variant="outline">{nativeIngress.authenticationMode.replaceAll("_", " ")}</Badge><Badge variant="outline">v{nativeIngress.version}</Badge></div><span className="text-xs text-muted-foreground">{nativeIngress.lastInboundEventAt ? `Last signal ${new Date(nativeIngress.lastInboundEventAt).toLocaleString()}` : "No verified signals received"}</span></div>
        <div><p className="text-xs font-medium uppercase tracking-wide text-muted-foreground">Provider callback URL</p><code className="mt-1 block break-all rounded bg-muted p-2 text-xs">{nativeIngress.endpointUrl || nativeIngress.endpointPath}</code></div>
        <p className="text-xs text-muted-foreground">Authority scope: {nativeIngress.providerAccountReference}</p>
        {nativeIngress.provider === "gmail" && <div className="rounded-lg bg-muted p-3 text-xs"><p>Topic: {nativeIngress.topicName}</p><p>Subscription: {nativeIngress.providerSubscriptionReference}</p><p>{nativeIngress.watchExpiresAt ? `Watch expires ${new Date(nativeIngress.watchExpiresAt).toLocaleString()}` : "Mailbox watch has not been started."}</p>{nativeWatchAttempts[0] && <p className="mt-1">Latest renewal: {nativeWatchAttempts[0].outcome.replaceAll("_", " ")} · attempt {nativeWatchAttempts[0].attemptNumber}</p>}</div>}
        {["google_drive", "google_calendar"].includes(nativeIngress.provider) && <div className="rounded-lg bg-muted p-3 text-xs"><p>Collection: {nativeIngress.resourceCollectionReference}</p><p>Channel: {nativeIngress.providerSubscriptionReference || "Not started"}</p><p>Resource receipt: {nativeIngress.providerResourceReference || "Not received"}</p><p>{nativeIngress.watchExpiresAt ? `Channel expires ${new Date(nativeIngress.watchExpiresAt).toLocaleString()}` : "Resource channel has not been started."}</p>{nativeWatchAttempts[0] && <p className="mt-1">Latest renewal: {nativeWatchAttempts[0].outcome.replaceAll("_", " ")} · attempt {nativeWatchAttempts[0].attemptNumber}</p>}</div>}
        {nativeIngress.provider === "notion" && nativeIngress.verificationTokenAvailable && canDecide && <Button variant="outline" disabled={!providerIngressForm.evidenceId} onClick={() => action.mutate({ url: `${providerIngressEndpoint}/${nativeIngress.id}/verification-token`, body: { expectedVersion: nativeIngress.version, evidenceIds: [providerIngressForm.evidenceId] }, success: "Notion verification token revealed" }, { onSuccess: (value: any) => setRevealedNotionToken(value.verificationToken) })}><Copy className="mr-2 h-4 w-4"/>Reveal verification token</Button>}
        {revealedNotionToken && <div className="flex gap-2"><Input readOnly aria-label="Notion verification token" value={revealedNotionToken}/><Button variant="outline" aria-label="Copy Notion verification token" onClick={async () => navigator.clipboard.writeText(revealedNotionToken)}><Copy className="h-4 w-4"/></Button></div>}
        {nativePolicy && <details className="border-t pt-3"><summary className="cursor-pointer text-sm font-medium">Service objectives and escalation</summary><div className="mt-3 grid gap-3 md:grid-cols-2"><label className="space-y-1 text-xs font-medium">Watch renewal lead time (minutes)<Input type="number" min={5} max={8640} value={providerPolicyForm.watchRenewBeforeMinutes} onChange={(event) => setProviderPolicyForm((value) => ({ ...value, watchRenewBeforeMinutes: Number(event.target.value) }))}/></label><label className="space-y-1 text-xs font-medium">Reconciliation overdue after (minutes)<Input type="number" min={5} max={1440} value={providerPolicyForm.reconciliationOverdueMinutes} onChange={(event) => setProviderPolicyForm((value) => ({ ...value, reconciliationOverdueMinutes: Number(event.target.value) }))}/></label><label className="space-y-1 text-xs font-medium">Verification warning after (minutes)<Input type="number" min={5} max={10080} value={providerPolicyForm.pendingVerificationMinutes} onChange={(event) => setProviderPolicyForm((value) => ({ ...value, pendingVerificationMinutes: Number(event.target.value) }))}/></label><label className="space-y-1 text-xs font-medium">Maximum delivery attempts<Input type="number" min={1} max={10} value={providerPolicyForm.maxDeliveryAttempts} onChange={(event) => setProviderPolicyForm((value) => ({ ...value, maxDeliveryAttempts: Number(event.target.value) }))}/></label><label className="space-y-1 text-xs font-medium">Minimum external severity<select className={`${field} w-full`} value={providerPolicyForm.minimumEscalationSeverity} onChange={(event) => setProviderPolicyForm((value) => ({ ...value, minimumEscalationSeverity: event.target.value }))}><option value="warning">Warning</option><option value="material">Material</option><option value="critical">Critical</option></select></label><label className="flex items-center gap-2 self-end rounded-lg border p-3 text-sm"><input type="checkbox" checked={providerPolicyForm.externalEscalationEnabled} onChange={(event) => setProviderPolicyForm((value) => ({ ...value, externalEscalationEnabled: event.target.checked }))}/><span>Send signed external escalations</span></label><p className={`text-xs md:col-span-2 ${providerIngress.data?.externalReceiverConfigured ? "text-emerald-700" : "text-amber-800"}`}>{providerIngress.data?.externalReceiverConfigured ? "The deployment has an approved signed operational-alert receiver." : "No deployment alert receiver is configured. Enabled alerts will retain bounded retry and dead-letter custody until operations configures it."}</p>{canDecide && <>{evidenceSelect("Service objective Evidence", providerPolicyForm.evidenceId, (evidenceId) => setProviderPolicyForm((value) => ({ ...value, evidenceId })))}<Textarea className="md:col-span-2" aria-label="Service objective rationale" placeholder="Why these thresholds and escalation boundaries fit this provider and organization" value={providerPolicyForm.rationale} onChange={(event) => setProviderPolicyForm((value) => ({ ...value, rationale: event.target.value }))}/><Button className="w-fit" disabled={!providerPolicyForm.evidenceId || providerPolicyForm.rationale.trim().length < 20 || action.isPending} onClick={() => runAction(`${providerIngressEndpoint}/${nativeIngress.id}/policy`, { expectedVersion: nativePolicy.version, watchRenewBeforeMinutes: providerPolicyForm.watchRenewBeforeMinutes, reconciliationOverdueMinutes: providerPolicyForm.reconciliationOverdueMinutes, pendingVerificationMinutes: providerPolicyForm.pendingVerificationMinutes, externalEscalationEnabled: providerPolicyForm.externalEscalationEnabled, minimumEscalationSeverity: providerPolicyForm.minimumEscalationSeverity, maxDeliveryAttempts: providerPolicyForm.maxDeliveryAttempts, rationale: providerPolicyForm.rationale, evidenceIds: [providerPolicyForm.evidenceId] }, "Provider service objectives updated")}>Save service objectives</Button></>}</div></details>}
        {canDecide && <div className="grid gap-2 border-t pt-3 md:grid-cols-3">{evidenceSelect("Provider ingress Evidence", providerIngressForm.evidenceId, (evidenceId) => setProviderIngressForm((value) => ({ ...value, evidenceId })))}{["gmail", "google_drive", "google_calendar"].includes(nativeIngress.provider) && nativeIngress.state !== "revoked" && <><label className="flex items-start gap-2 text-sm"><input className="mt-1" type="checkbox" checked={providerIngressForm.confirmed} onChange={(event) => setProviderIngressForm((value) => ({ ...value, confirmed: event.target.checked }))}/><span>Start or renew the external {nativeIngress.provider === "gmail" ? "Gmail mailbox" : nativeIngress.provider === "google_drive" ? "Drive resource" : "Calendar resource"} watch.</span></label><Button disabled={!providerIngressForm.evidenceId || !providerIngressForm.confirmed} onClick={() => runAction(`${providerIngressEndpoint}/${nativeIngress.id}/${nativeIngress.provider === "gmail" ? "start-gmail-watch" : "start-google-channel"}`, { expectedVersion: nativeIngress.version, confirmExternalEffect: true, evidenceIds: [providerIngressForm.evidenceId] }, nativeIngress.state === "active" ? "Provider watch renewed" : "Provider watch started")}>{nativeIngress.state === "active" ? "Renew provider watch" : "Start provider watch"}</Button></>}{nativeIngress.state === "active" && <Button variant="destructive" disabled={!providerIngressForm.evidenceId} onClick={() => runAction(`${providerIngressEndpoint}/${nativeIngress.id}/state`, { expectedVersion: nativeIngress.version, state: "revoked", evidenceIds: [providerIngressForm.evidenceId] }, "Provider ingress revoked")}>Revoke ingress</Button>}</div>}
        {canDecide && <details className="border-t pt-3"><summary className="cursor-pointer text-sm font-medium">Rotate provider configuration</summary><div className="mt-3 grid gap-2 md:grid-cols-2">
          {["notion", "gmail"].includes(nativeIngress.provider) && <Input aria-label="Replacement provider subscription" placeholder={nativeIngress.providerSubscriptionReference} value={providerRotation.providerSubscriptionReference} onChange={(event) => setProviderRotation((value) => ({ ...value, providerSubscriptionReference: event.target.value }))}/>}
          {nativeIngress.provider === "google_drive" && <Input readOnly aria-label="Replacement resource collection" value="changes"/>}
          {nativeIngress.provider === "google_calendar" && <Input aria-label="Replacement resource collection" placeholder={nativeIngress.resourceCollectionReference} value={providerRotation.resourceCollectionReference} onChange={(event) => setProviderRotation((value) => ({ ...value, resourceCollectionReference: event.target.value }))}/>}
          {nativeIngress.provider === "gmail" && <><Input aria-label="Replacement Gmail topic" placeholder={nativeIngress.topicName} value={providerRotation.topicName} onChange={(event) => setProviderRotation((value) => ({ ...value, topicName: event.target.value }))}/><Input aria-label="Replacement push audience" placeholder={nativeIngress.audience} value={providerRotation.audience} onChange={(event) => setProviderRotation((value) => ({ ...value, audience: event.target.value }))}/><Input aria-label="Replacement push service account" placeholder={nativeIngress.serviceAccountEmail} value={providerRotation.serviceAccountEmail} onChange={(event) => setProviderRotation((value) => ({ ...value, serviceAccountEmail: event.target.value }))}/></>}
          {evidenceSelect("Provider rotation Evidence", providerRotation.evidenceId, (evidenceId) => setProviderRotation((value) => ({ ...value, evidenceId })))}<Textarea className="md:col-span-2" aria-label="Provider rotation rationale" placeholder="Why the provider subscription, resource collection, or push identity must change, and how the replacement was verified" value={providerRotation.rationale} onChange={(event) => setProviderRotation((value) => ({ ...value, rationale: event.target.value }))}/>
          {["gmail", "google_drive", "google_calendar"].includes(nativeIngress.provider) && nativeIngress.state === "active" && <label className="flex items-start gap-2 text-sm md:col-span-2"><input className="mt-1" type="checkbox" checked={providerRotation.confirmed} onChange={(event) => setProviderRotation((value) => ({ ...value, confirmed: event.target.checked }))}/><span>I approve stopping the current external watch. The replacement watch must be started after rotation.</span></label>}
          <Button variant="outline" className="w-fit" disabled={!providerRotation.evidenceId || providerRotation.rationale.trim().length < 20 || (["notion", "gmail"].includes(nativeIngress.provider) && !(providerRotation.providerSubscriptionReference || nativeIngress.providerSubscriptionReference)) || (nativeIngress.provider === "google_calendar" && !(providerRotation.resourceCollectionReference || nativeIngress.resourceCollectionReference)) || (nativeIngress.provider === "gmail" && (!(providerRotation.topicName || nativeIngress.topicName) || !(providerRotation.audience || nativeIngress.audience) || !(providerRotation.serviceAccountEmail || nativeIngress.serviceAccountEmail))) || (["gmail", "google_drive", "google_calendar"].includes(nativeIngress.provider) && nativeIngress.state === "active" && !providerRotation.confirmed)} onClick={() => { setRevealedNotionToken(""); runAction(`${providerIngressEndpoint}/${nativeIngress.id}/rotate-configuration`, { expectedVersion: nativeIngress.version, providerSubscriptionReference: ["notion", "gmail"].includes(nativeIngress.provider) ? providerRotation.providerSubscriptionReference || nativeIngress.providerSubscriptionReference : "", resourceCollectionReference: nativeIngress.provider === "google_drive" ? "changes" : nativeIngress.provider === "google_calendar" ? providerRotation.resourceCollectionReference || nativeIngress.resourceCollectionReference : "", topicName: nativeIngress.provider === "gmail" ? providerRotation.topicName || nativeIngress.topicName : "", audience: nativeIngress.provider === "gmail" ? providerRotation.audience || nativeIngress.audience : "", serviceAccountEmail: nativeIngress.provider === "gmail" ? providerRotation.serviceAccountEmail || nativeIngress.serviceAccountEmail : "", confirmExternalEffect: ["gmail", "google_drive", "google_calendar"].includes(nativeIngress.provider) && nativeIngress.state === "active" ? providerRotation.confirmed : false, rationale: providerRotation.rationale, evidenceIds: [providerRotation.evidenceId] }, "Provider ingress configuration rotated"); }}><RotateCcw className="mr-2 h-4 w-4"/>Rotate configuration</Button><p className="text-xs text-muted-foreground md:col-span-2">Rotation clears prior verification and watch cursors. Old callbacks stop matching immediately; complete the new provider handshake before relying on ingress.</p>
        </div></details>}
      </div> : canDecide ? <div className="grid gap-2 rounded-xl border p-4 md:grid-cols-2">
        <Input placeholder={nativeProvider === "notion" ? "Exact Notion workspace ID" : "Exact authorized Google account email"} value={providerIngressForm.providerAccountReference || selectedBinding.providerAccountReference || ""} onChange={(event) => setProviderIngressForm((value) => ({ ...value, providerAccountReference: event.target.value }))}/>
        {nativeProvider === "notion" && <Input placeholder="Notion subscription ID (recommended)" value={providerIngressForm.providerSubscriptionReference} onChange={(event) => setProviderIngressForm((value) => ({ ...value, providerSubscriptionReference: event.target.value }))}/>}
        {nativeProvider === "gmail" && <><Input placeholder="projects/project/subscriptions/subscription" value={providerIngressForm.providerSubscriptionReference} onChange={(event) => setProviderIngressForm((value) => ({ ...value, providerSubscriptionReference: event.target.value }))}/><Input placeholder="projects/project/topics/gmail" value={providerIngressForm.topicName} onChange={(event) => setProviderIngressForm((value) => ({ ...value, topicName: event.target.value }))}/><Input placeholder="https://entrepreneuros.net/api/eos/provider-ingress/..." value={providerIngressForm.audience} onChange={(event) => setProviderIngressForm((value) => ({ ...value, audience: event.target.value }))}/><Input placeholder="push-auth@project.iam.gserviceaccount.com" value={providerIngressForm.serviceAccountEmail} onChange={(event) => setProviderIngressForm((value) => ({ ...value, serviceAccountEmail: event.target.value }))}/></>}
        {nativeProvider === "google_drive" && <Input readOnly aria-label="Google Drive resource collection" value="changes"/>}
        {nativeProvider === "google_calendar" && <Input placeholder="Calendar ID, for example primary" value={providerIngressForm.resourceCollectionReference} onChange={(event) => setProviderIngressForm((value) => ({ ...value, resourceCollectionReference: event.target.value }))}/>}
        {evidenceSelect("Provider ingress provisioning Evidence", providerIngressForm.evidenceId, (evidenceId) => setProviderIngressForm((value) => ({ ...value, evidenceId })))}
        <Button disabled={!providerIngressForm.evidenceId || !(providerIngressForm.providerAccountReference || selectedBinding.providerAccountReference) || (nativeProvider === "gmail" && (!providerIngressForm.providerSubscriptionReference || !providerIngressForm.topicName || !providerIngressForm.audience || !providerIngressForm.serviceAccountEmail)) || (nativeProvider === "google_calendar" && !providerIngressForm.resourceCollectionReference)} onClick={() => runAction(`${endpoint}/bindings/${bindingId}/provider-ingress`, { provider: nativeProvider, providerAccountReference: providerIngressForm.providerAccountReference || selectedBinding.providerAccountReference, providerSubscriptionReference: nativeProvider === "notion" || nativeProvider === "gmail" ? providerIngressForm.providerSubscriptionReference : "", resourceCollectionReference: nativeProvider === "google_drive" ? "changes" : nativeProvider === "google_calendar" ? providerIngressForm.resourceCollectionReference : "", topicName: nativeProvider === "gmail" ? providerIngressForm.topicName : "", audience: nativeProvider === "gmail" ? providerIngressForm.audience : "", serviceAccountEmail: nativeProvider === "gmail" ? providerIngressForm.serviceAccountEmail : "", evidenceIds: [providerIngressForm.evidenceId] }, "Provider-native ingress configured")}>Configure native ingress</Button>
      </div> : <p className="text-sm text-muted-foreground">No provider-native ingress registration is visible in this authority scope.</p>}
      <div className="space-y-2"><div className="flex items-center justify-between"><p className="text-sm font-medium">Native signal inbox</p><Badge variant="secondary">{nativeIngressEvents.length}</Badge></div>{nativeIngressEvents.length ? nativeIngressEvents.slice(0, 25).map((item: Row) => { const latestAttempt = nativeReconciliationAttempts.find((attempt: Row) => attempt.eventId === item.id); return <div key={item.id} className="rounded-lg border p-3 text-xs"><div className="flex flex-wrap justify-between gap-2"><span className="font-medium">{item.eventType}</span><div className="flex gap-2">{badge(item.processingState)}{latestAttempt && badge(latestAttempt.outcome)}</div></div><p className="mt-1 break-all">{item.providerObjectReference}</p><p className="mt-1 text-muted-foreground">Verified by {item.verificationMethod.replaceAll("_", " ")}</p>{latestAttempt && <p className="mt-1 text-muted-foreground">Attempt {latestAttempt.attemptNumber}: {latestAttempt.summary}</p>}{latestAttempt?.outcome === "dead_letter" && canDecide && <div className="mt-3 grid gap-2 border-t pt-3"><Textarea aria-label={`Replay rationale for ${item.eventType}`} placeholder="Why replay is safe after correcting the provider or authorization failure" value={providerReplay.rationale} onChange={(event) => setProviderReplay((value) => ({ ...value, rationale: event.target.value }))}/>{evidenceSelect(`Replay Evidence for ${item.eventType}`, providerReplay.evidenceId, (evidenceId) => setProviderReplay((value) => ({ ...value, evidenceId })))}<Button variant="outline" disabled={!providerReplay.evidenceId || providerReplay.rationale.trim().length < 20 || action.isPending} onClick={() => runAction(`${providerIngressEndpoint}/events/${item.id}/replay`, { rationale: providerReplay.rationale, evidenceIds: [providerReplay.evidenceId] }, "Dead-lettered provider signal replayed")}><RotateCcw className="mr-2 h-4 w-4"/>Replay reconciliation</Button></div>}</div>; }) : <p className="text-sm text-muted-foreground">No verified provider-native signals have arrived for this binding.</p>}</div>
      {nativeIngress && ["notion", "google_drive", "google_calendar"].includes(nativeIngress.provider) && <div className="space-y-2"><div className="flex items-center justify-between"><div><p className="text-sm font-medium">Reconciled resource snapshots</p><p className="text-xs text-muted-foreground">Bounded provider reads retain selected metadata, revision and integrity hashes—never Drive file contents, Calendar descriptions, or Notion page bodies in this projection.</p></div><Badge variant="secondary">{nativeResourceSnapshots.length}</Badge></div>{nativeResourceSnapshots.length ? nativeResourceSnapshots.slice(0, 25).map((item: Row) => <div key={item.id} className="rounded-lg border p-3 text-xs"><div className="flex flex-wrap items-start justify-between gap-2"><div><p className="font-medium">{item.title}</p><p className="mt-1 break-all text-muted-foreground">Provider revision {item.providerRevision}</p></div><div className="flex gap-2">{badge(item.resourceState || "active")}{item.truncated ? <Badge variant="secondary">bounded snapshot</Badge> : <Badge variant="outline">complete within limit</Badge>}</div></div><code className="mt-2 block break-all">{item.boundedContentSha256}</code><div className="mt-2 flex flex-wrap gap-3">{item.providerUrl && <a className="font-medium text-primary underline-offset-4 hover:underline" href={item.providerUrl} target="_blank" rel="noreferrer">Open verified provider resource</a>}{item.previousSnapshotSha256 && <span className="text-muted-foreground">Chained to {item.previousSnapshotSha256.slice(0, 12)}…</span>}</div></div>) : <p className="text-sm text-muted-foreground">No resource signal has completed bounded provider reconciliation.</p>}</div>}
    </CardContent></Card>

    {selectedBinding && currentManifest && <div className="grid gap-6 xl:grid-cols-2"><Card><CardHeader><CardTitle className="flex items-center gap-2"><Activity className="h-5 w-5"/>Governed run queue</CardTitle><CardDescription>Planning stores a hashed request and idempotency key without claiming execution. Approved allowlisted operations can then be dispatched through the deployment-controlled provider boundary.</CardDescription></CardHeader><CardContent className="space-y-4">
      {canExecute && <details><summary className="cursor-pointer text-sm font-medium">Plan a run</summary><div className="mt-3 grid gap-2"><select aria-label="Declared operation" className={field} value={run.operation} onChange={(e) => setRun((v) => ({ ...v, operation: e.target.value }))}><option value="">Choose declared operation</option>{(currentManifest.operations || []).map((value: string) => <option key={value}>{value}</option>)}</select><Input placeholder="Idempotency key" value={run.idempotencyKey} onChange={(e) => setRun((v) => ({ ...v, idempotencyKey: e.target.value }))}/><Input placeholder="Local work/request reference" value={run.requestReference} onChange={(e) => setRun((v) => ({ ...v, requestReference: e.target.value }))}/><Textarea aria-label="Request shape JSON" value={run.requestShape} onChange={(e) => setRun((v) => ({ ...v, requestShape: e.target.value }))}/><select aria-label="Run owner" className={field} value={run.ownerSeatId} onChange={(e) => setRun((v) => ({ ...v, ownerSeatId: e.target.value }))}><option value="">Choose accountable seat</option>{(state.data?.seats || []).map((item: Row) => <option key={item.id} value={item.id}>{item.title}</option>)}</select><Button disabled={!run.operation || run.idempotencyKey.length < 8 || !run.requestReference || !run.ownerSeatId} onClick={() => { const shape = parseShape(run.requestShape); if (shape) runAction(`${endpoint}/runs`, { integrationBindingId: bindingId, operation: run.operation, idempotencyKey: run.idempotencyKey, requestReference: run.requestReference, requestShape: shape, maxAttempts: run.maxAttempts, ownerSeatId: run.ownerSeatId, classification: run.classification }, "Governed run planned"); }}>Plan without claiming execution</Button></div></details>}
      <select aria-label="Integration run" className={`${field} w-full`} value={runId} onChange={(e) => setRunId(e.target.value)}><option value="">Choose run</option>{runs.map((item: Row) => <option key={item.id} value={item.id}>{item.operation} · {item.state} · attempt {item.attemptCount}/{item.maxAttempts}</option>)}</select>
      {selectedRun && <div className="rounded-xl border p-4"><div className="flex gap-2">{badge(selectedRun.state)}<Badge variant="outline">v{selectedRun.version}</Badge>{selectedRun.providerExecutionId && <Badge variant="outline">dispatch claimed</Badge>}</div><p className="mt-2 font-medium">{selectedRun.operation}</p><p className="text-xs text-muted-foreground">{selectedRun.requestReference} · {selectedRun.idempotencyKey}</p><code className="mt-2 block break-all text-[10px]">{selectedRun.requestSha256}</code>{["planned", "retry_ready"].includes(selectedRun.state) && canApprove && (state.data?.executionCapability?.operations || []).includes(selectedRun.operation) && <div className="mt-4 grid gap-2 border-t pt-4">{evidenceSelect("Provider execution approval Evidence", execution.evidenceId, (evidenceId) => setExecution((value) => ({ ...value, evidenceId })))}<label className="flex items-start gap-2 text-sm"><input className="mt-1" type="checkbox" checked={execution.confirmed} onChange={(event) => setExecution((value) => ({ ...value, confirmed: event.target.checked }))}/><span>I approve this exact request and understand it can create an external provider effect.</span></label><Button className="w-fit" disabled={!state.data?.executionCapability?.enabled || !execution.evidenceId || !execution.confirmed || action.isPending} onClick={() => runAction(`${endpoint}/runs/${runId}/execute`, { expectedVersion: selectedRun.version, confirmExternalEffect: true, evidenceIds: [execution.evidenceId] }, "Allowlisted provider operation dispatched")}><PlugZap className="mr-2 h-4 w-4"/>Execute approved operation</Button>{!state.data?.executionCapability?.enabled && <p className="text-xs text-muted-foreground">Deployment kill switch is off. The run remains safely planned.</p>}</div>}</div>}
    </CardContent></Card>

    <Card><CardHeader><CardTitle>Immutable execution receipt</CardTitle><CardDescription>Record only what the provider, reconciliation process, manual attestor, or fixture actually proved.</CardDescription></CardHeader><CardContent className="space-y-3">
      {selectedRun && ["planned", "retry_ready", "dispatching"].includes(selectedRun.state) && canExecute && <div className="grid gap-2">{selectedRun.state === "dispatching" && <Alert variant="destructive"><AlertTriangle className="h-4 w-4"/><AlertTitle>Provider outcome requires reconciliation</AlertTitle><AlertDescription>Do not execute this request again. Verify the external provider state, attach receipt Evidence, and record the observed outcome below.</AlertDescription></Alert>}<div className="grid grid-cols-2 gap-2"><select aria-label="Receipt outcome" className={field} value={receipt.outcome} onChange={(e) => setReceipt((v) => ({ ...v, outcome: e.target.value }))}>{["succeeded", "failed", "uncertain"].map((value) => <option key={value}>{value}</option>)}</select>{selectedRun.state === "dispatching" ? <div className={`${field} flex items-center text-muted-foreground`} aria-label="Receipt authority">reconciled</div> : <select aria-label="Receipt authority" className={field} value={receipt.authority} onChange={(e) => setReceipt((v) => ({ ...v, authority: e.target.value }))}>{["provider_receipt", "reconciled", "manual_attestation", "fixture"].map((value) => <option key={value}>{value.replaceAll("_", " ")}</option>)}</select>}</div><Input placeholder="Durable external/provider reference" value={receipt.externalReference} onChange={(e) => setReceipt((v) => ({ ...v, externalReference: e.target.value }))}/><Textarea placeholder="Observed outcome and known limits" value={receipt.summary} onChange={(e) => setReceipt((v) => ({ ...v, summary: e.target.value }))}/><Textarea aria-label="Response shape JSON" value={receipt.responseShape} onChange={(e) => setReceipt((v) => ({ ...v, responseShape: e.target.value }))}/>{evidenceSelect("Receipt Evidence", receipt.evidenceId, (evidenceId) => setReceipt((v) => ({ ...v, evidenceId })))}<Button disabled={!receipt.evidenceId || receipt.externalReference.length < 3 || receipt.summary.trim().length < 10} onClick={() => { const shape = parseShape(receipt.responseShape); if (shape) runAction(`${endpoint}/runs/${runId}/receipts`, { expectedVersion: selectedRun.version, outcome: receipt.outcome, authority: selectedRun.state === "dispatching" ? "reconciled" : receipt.authority, externalReference: receipt.externalReference, summary: receipt.summary, responseShape: shape, latencyMs: receipt.latencyMs ? Number(receipt.latencyMs) : undefined, evidenceIds: [receipt.evidenceId] }, selectedRun.state === "dispatching" ? "Provider outcome reconciled" : "Execution receipt recorded"); }}>Record immutable receipt</Button></div>}
      {selectedRun && ["failed", "uncertain"].includes(selectedRun.state) && selectedRun.attemptCount < selectedRun.maxAttempts && canDecide && <div className="grid gap-2 border-t pt-3"><Textarea placeholder="Why another attempt is safe and authorized" value={retry.rationale} onChange={(e) => setRetry((v) => ({ ...v, rationale: e.target.value }))}/>{evidenceSelect("Retry Evidence", retry.evidenceId, (evidenceId) => setRetry((v) => ({ ...v, evidenceId })))}<Button variant="outline" disabled={!retry.evidenceId || retry.rationale.trim().length < 20} onClick={() => runAction(`${endpoint}/runs/${runId}/retries`, { expectedVersion: selectedRun.version, rationale: retry.rationale, evidenceIds: [retry.evidenceId] }, "Retry authorized")}>Authorize next attempt</Button></div>}
      <div className="space-y-2">{receipts.map((item: Row) => <div key={item.id} className="rounded-lg border p-3 text-xs"><div className="flex justify-between gap-2"><span>{badge(item.outcome)} {item.authority.replaceAll("_", " ")}</span><span>attempt {item.attemptNumber}</span></div><p className="mt-2">{item.summary}</p><code className="mt-1 block break-all text-[10px]">{item.receiptSha256}</code></div>)}</div>
      {providerExecutions.length > 0 && <div className="space-y-2 border-t pt-3"><p className="text-xs font-medium uppercase tracking-wide text-muted-foreground">Provider execution claims</p>{providerExecutions.map((item: Row) => <div key={item.id} className="rounded-lg border p-3 text-xs"><div className="flex justify-between gap-2">{badge(item.status)}<span>{item.reconciliationStatus.replaceAll("_", " ")}</span></div><p className="mt-1">{item.provider} · {item.operation}</p><code className="mt-1 block break-all text-[10px]">{item.id}</code></div>)}</div>}
    </CardContent></Card></div>}

    {selectedBinding && <Card><CardHeader><CardTitle className="flex items-center gap-2"><AlertTriangle className="h-5 w-5"/>Incident and recovery queue</CardTitle><CardDescription>Failed and uncertain receipts open incidents automatically against the binding's declared recovery owner and plan.</CardDescription></CardHeader><CardContent className="space-y-3">{incidents.length ? incidents.map((item: Row) => { const note = incidentNotes[item.id] || { rationale: "", evidenceId: "" }; return <div key={item.id} className="rounded-xl border p-4"><div className="flex flex-wrap justify-between gap-2"><div className="flex gap-2">{badge(item.state)}{badge(item.severity)}</div><span className="text-xs">v{item.version}</span></div><p className="mt-2 font-medium">{item.summary}</p><p className="mt-1 text-sm text-muted-foreground">Recovery: {item.recoveryPlan}</p>{item.state !== "resolved" && canDecide && <div className="mt-3 grid gap-2 md:grid-cols-3"><Textarea placeholder="Acknowledgement or verified resolution" value={note.rationale} onChange={(e) => setIncidentNotes((v) => ({ ...v, [item.id]: { ...note, rationale: e.target.value } }))}/>{evidenceSelect("Incident Evidence", note.evidenceId, (evidenceId) => setIncidentNotes((v) => ({ ...v, [item.id]: { ...note, evidenceId } })))}<div className="flex gap-2"><Button variant="outline" disabled={item.state !== "open" || !note.evidenceId || note.rationale.length < 20} onClick={() => runAction(`${endpoint}/incidents/${item.id}/transitions`, { expectedVersion: item.version, state: "acknowledged", rationale: note.rationale, evidenceIds: [note.evidenceId] }, "Incident acknowledged")}>Acknowledge</Button><Button disabled={!note.evidenceId || note.rationale.length < 20} onClick={() => runAction(`${endpoint}/incidents/${item.id}/transitions`, { expectedVersion: item.version, state: "resolved", rationale: note.rationale, evidenceIds: [note.evidenceId] }, "Incident resolved")}>Resolve</Button></div></div>}</div>; }) : <p className="text-sm text-muted-foreground">No integration incidents in this authority scope.</p>}</CardContent></Card>}

    {selectedBinding && currentManifest && <Card><CardHeader><CardTitle className="flex items-center gap-2"><GitBranch className="h-5 w-5"/>Parity qualification and cutover</CardTitle><CardDescription>Native mode is founder-approved only after current-contract coverage, provider-backed successful receipts, non-fixture testing, and a validated rollback.</CardDescription></CardHeader><CardContent className="space-y-4">
      {canDecide && <details><summary className="cursor-pointer text-sm font-medium">Record qualification</summary><div className="mt-3 grid gap-2 md:grid-cols-2"><Input placeholder="Qualification key" value={qualification.qualificationKey} onChange={(e) => setQualification((v) => ({ ...v, qualificationKey: e.target.value }))}/><select aria-label="Qualification environment" className={field} value={qualification.environment} onChange={(e) => setQualification((v) => ({ ...v, environment: e.target.value }))}>{["fixture", "sandbox", "production"].map((value) => <option key={value}>{value}</option>)}</select><select aria-label="Qualification outcome" className={field} value={qualification.outcome} onChange={(e) => setQualification((v) => ({ ...v, outcome: e.target.value }))}>{["passing", "failing", "accepted_exception"].map((value) => <option key={value}>{value.replaceAll("_", " ")}</option>)}</select><Input placeholder="Tested operations, comma separated" value={qualification.testedOperations} onChange={(e) => setQualification((v) => ({ ...v, testedOperations: e.target.value }))}/><Input placeholder="Missing capabilities, comma separated" value={qualification.missingCapabilities} onChange={(e) => setQualification((v) => ({ ...v, missingCapabilities: e.target.value }))}/>{evidenceSelect("Qualification Evidence", qualification.evidenceId, (evidenceId) => setQualification((v) => ({ ...v, evidenceId })))}<Textarea className="md:col-span-2" placeholder="Parity results, failure observations, and evidence limits" value={qualification.testSummary} onChange={(e) => setQualification((v) => ({ ...v, testSummary: e.target.value }))}/><label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={qualification.rollbackValidated} onChange={(e) => setQualification((v) => ({ ...v, rollbackValidated: e.target.checked }))}/>Rollback procedure was actually tested</label><Button className="w-fit" disabled={!qualification.evidenceId || !qualification.qualificationKey || qualification.testSummary.trim().length < 20 || !csv(qualification.testedOperations).length} onClick={() => runAction(`${endpoint}/qualifications`, { integrationBindingId: bindingId, manifestId: currentManifest.id, qualificationKey: qualification.qualificationKey, environment: qualification.environment, outcome: qualification.outcome, testedOperations: csv(qualification.testedOperations), missingCapabilities: csv(qualification.missingCapabilities), testSummary: qualification.testSummary, rollbackValidated: qualification.rollbackValidated, evidenceIds: [qualification.evidenceId] }, "Parity qualification recorded")}>Record qualification</Button></div></details>}
      <div className="space-y-2">{qualifications.map((item: Row) => <div key={item.id} className="rounded-lg border p-3 text-sm"><div className="flex flex-wrap gap-2">{badge(item.outcome)}<Badge variant="outline">{item.environment}</Badge>{item.rollbackValidated && <Badge variant="outline">rollback tested</Badge>}</div><p className="mt-2 font-medium">{item.qualificationKey}</p><p className="text-muted-foreground">{item.testSummary}</p></div>)}</div>
      {currentQualification && operational && canApprove && <div className="grid gap-2 rounded-xl border border-primary/30 p-4 md:grid-cols-2"><div className="md:col-span-2"><p className="font-medium">Founder-controlled cutover decision</p><p className="text-sm text-muted-foreground">Current mode {operational.trafficMode}; qualification {currentQualification.outcome} in {currentQualification.environment}.</p></div><select aria-label="Cutover decision" className={field} value={cutover.decision} onChange={(e) => setCutover((v) => ({ ...v, decision: e.target.value }))}>{["approve_native", "retain_provider", "rollback_to_provider"].map((value) => <option key={value}>{value.replaceAll("_", " ")}</option>)}</select>{evidenceSelect("Cutover Evidence", cutover.evidenceId, (evidenceId) => setCutover((v) => ({ ...v, evidenceId })))}<Textarea className="md:col-span-2" placeholder="Decision rationale, evidence, and rollback ownership" value={cutover.rationale} onChange={(e) => setCutover((v) => ({ ...v, rationale: e.target.value }))}/><Button className="w-fit" disabled={!cutover.evidenceId || cutover.rationale.trim().length < 20} onClick={() => runAction(`${endpoint}/bindings/${bindingId}/cutovers`, { expectedOperationalVersion: operational.version, qualificationId: currentQualification.id, decision: cutover.decision, rationale: cutover.rationale, evidenceIds: [cutover.evidenceId] }, "Cutover decision recorded")}><CheckCircle2 className="mr-2 h-4 w-4"/>Record cutover decision</Button></div>}
    </CardContent></Card>}

    {selectedBinding && <Card><CardHeader><CardTitle>Immutable adapter history</CardTitle><CardDescription>Hash-chained events preserve configuration-derived manifests, requests, receipts, incidents, recovery, qualification, and traffic-mode decisions.</CardDescription></CardHeader><CardContent><div className="space-y-2">{events.map((item: Row) => <div key={item.id} className="rounded-lg border p-3 text-xs"><div className="flex justify-between gap-2"><span className="font-medium">{item.eventType.replaceAll("_", " ")}</span><span>v{item.versionBefore}→{item.versionAfter}</span></div><code className="mt-1 block break-all text-[10px] text-muted-foreground">{item.eventSha256}</code></div>)}</div></CardContent></Card>}
  </div>;
}
